const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([157.706220, -34.344553]);
    const geom = point.buffer(100000); // 100 km radius

    const prevStart = '2018-11-01';
    const prevEnd = '2019-03-01'; // end is exclusive; covers Nov-Feb
    const currStart = '2019-11-01';
    const currEnd = '2020-03-01';

    // 2. Helper: get a BC AOD collection with fallback
    async function getBCCollection(start, end) {
      const ids = [
        'NASA/GEOS/MERRA2/M2T1NXAER', // hourly
        'NASA/GEOS/MERRA2/M2TMNXAER'  // monthly
      ];
      for (let i = 0; i < ids.length; i++) {
        try {
          const col = ee.ImageCollection(ids[i]).select('BCEXTTAU').filterDate(start, end);
          const size = await col.size().getInfo();
          if (size > 0) {
            return { id: ids[i], col: col, size: size };
          }
        } catch (e) {
          // Try next dataset
        }
      }
      return null;
    }

    // 3. Stats computation
    async function computeStats(wrapper) {
      const img = wrapper.col.mean();
      const meanDict = await img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: 30000,
        maxPixels: 1e9,
        bestEffort: true
      }).getInfo();

      const countDict = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 30000,
        maxPixels: 1e9,
        bestEffort: true
      }).getInfo();

      const mean = meanDict ? meanDict.BCEXTTAU : null;
      const count = countDict ? countDict.BCEXTTAU : 0;

      return { mean, count };
    }

    function isValid(val) {
      return typeof val === 'number' && isFinite(val) && val >= 0 && val <= 5;
    }

    // 4. Acquire collections
    const prevWrap = await getBCCollection(prevStart, prevEnd);
    const currWrap = await getBCCollection(currStart, currEnd);

    if (!prevWrap || !currWrap) {
      console.log(`Prev Images: ${prevWrap ? prevWrap.size : 0}`);
      console.log(`Curr Images: ${currWrap ? currWrap.size : 0}`);
      console.log('C1');
      return;
    }

    // 5. Compute stats
    const prevStats = await computeStats(prevWrap);
    const currStats = await computeStats(currWrap);

    console.log(`Prev Dataset: ${prevWrap.id}, Images: ${prevWrap.size}`);
    console.log(`Curr Dataset: ${currWrap.id}, Images: ${currWrap.size}`);

    if ((prevWrap.size > 0 && prevStats.count === 0) || (currWrap.size > 0 && currStats.count === 0)) {
      console.log(`Prev Valid Pixels: ${prevStats.count}, Curr Valid Pixels: ${currStats.count}`);
      console.log('C2');
      return;
    }

    if (!isValid(prevStats.mean) || !isValid(currStats.mean)) {
      console.log(`Prev Mean BC AOD: ${prevStats.mean}, Curr Mean BC AOD: ${currStats.mean}`);
      console.log('C3');
      return;
    }

    console.log(`Prev Mean BC AOD: ${prevStats.mean.toFixed(5)}, Pixels: ${prevStats.count}`);
    console.log(`Curr Mean BC AOD: ${currStats.mean.toFixed(5)}, Pixels: ${currStats.count}`);
    const delta = currStats.mean - prevStats.mean;
    const pct = prevStats.mean > 0 ? (delta / prevStats.mean) * 100 : null;
    console.log(`Delta: ${delta.toFixed(5)}${pct !== null ? ` (${pct.toFixed(1)}%)` : ''}`);

    // 6. Final Answer
    if (delta > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
